 let sx=0,sy=0,st=0;o.addEventListener('touchstart',e=>{const t=e.touches[0];sx=t.clientX;sy=t.clientY;st=Date.now()},{passive:true});
 o.addEventListener('touchend',e=>{if(e.target.closest('.tb'))return;const t=e.changedTouches[0];const dx=t.clientX-sx,dy=t.clientY-sy;const R=o.classList.contains('rot');const a=R?dy:dx,b=R?dx:dy;
  if(Math.abs(a)>40&&Math.abs(a)>Math.abs(b)){e.preventDefault();go(a<0?i+1:i-1);return}if(Math.abs(dx)<12&&Math.abs(dy)<12&&Date.now()-st<500){e.preventDefault();tap(t.clientX,t.clientY)}});
