/* ---------- PDF (16:9, one JPEG page per slide; built here, no library) ---------- */
function pdfBytes(imgs,title){const enc=new TextEncoder(),parts=[],offs=[];let len=0;const push=x=>{const b=typeof x==='string'?enc.encode(x):x;parts.push(b);len+=b.length};
 const PW=960,PH=540;const n=imgs.length;const obj=(k,body)=>{offs[k]=len;push(k+' 0 obj\n');body();push('\nendobj\n')};
 push('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n'.replace(/[\x80-\xff]/g,'A'));
 const hex=s=>{let h='FEFF';for(const c of s){const cp=c.codePointAt(0);if(cp>0xffff){const v=cp-0x10000;h+=(0xD800+(v>>10)).toString(16).padStart(4,'0')+(0xDC00+(v&1023)).toString(16).padStart(4,'0')}else h+=cp.toString(16).padStart(4,'0')}return '<'+h.toUpperCase()+'>'};
 const kids=[];for(let j=0;j<n;j++)kids.push((4+j*3)+' 0 R');
 obj(1,()=>push('<< /Type /Catalog /Pages 2 0 R >>'));obj(2,()=>push('<< /Type /Pages /Count '+n+' /Kids ['+kids.join(' ')+'] >>'));obj(3,()=>push('<< /Title '+hex(title||'محاضرة')+' /Producer (Zad) /Creator '+hex(APPN())+' >>'));
 imgs.forEach((im,j)=>{const p=4+j*3,c=p+1,x=p+2;const cs='q '+PW+' 0 0 '+PH+' 0 0 cm /Im0 Do Q';
  obj(p,()=>push('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+PW+' '+PH+'] /Resources << /XObject << /Im0 '+x+' 0 R >> >> /Contents '+c+' 0 R >>'));
  obj(c,()=>{push('<< /Length '+cs.length+' >>\nstream\n'+cs+'\nendstream')});
  obj(x,()=>{push('<< /Type /XObject /Subtype /Image /Width '+im.w+' /Height '+im.h+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+im.b.length+' >>\nstream\n');push(im.b);push('\nendstream')})});
 const total=4+n*3;const xref=len;let x='xref\n0 '+total+'\n0000000000 65535 f \n';for(let k=1;k<total;k++)x+=String(offs[k]).padStart(10,'0')+' 00000 n \n';
 push(x+'trailer\n<< /Size '+total+' /Root 1 0 R /Info 3 0 R >>\nstartxref\n'+xref+'\n%%EOF\n');
 const out=new Uint8Array(len);let o=0;for(const b of parts){out.set(b,o);o+=b.length}return out}
async function buildPdf(L,onp){await fonts();const P=pages(L);if(!P.length)throw new Error('empty');const W=1600,H=900;const cv=document.createElement('canvas');cv.width=W;cv.height=H;const ctx=cv.getContext('2d');const imgs=[];
 for(let j=0;j<P.length;j++){draw(ctx,W,H,L,P[j],j,P.length);const bl=await new Promise(r=>cv.toBlob(r,'image/jpeg',0.9));imgs.push({w:W,h:H,b:new Uint8Array(await bl.arrayBuffer())});onp&&onp(j+1,P.length);await new Promise(r=>setTimeout(r,0))}
 return pdfBytes(imgs,L.ti)}
const fname=L=>((APPN()+' - '+(L.ti||'محاضرة')).replace(/[\\/:*?"<>|]+/g,' ').trim().slice(0,80))+'.pdf';
async function exportPdf(L,share){const btn=$('#zlpdf');const old=btn&&btn.innerHTML;try{if(btn){btn.disabled=true}
 const bytes=await buildPdf(L,(a,b)=>{if(btn)btn.textContent='جارٍ التجهيز '+ar(a)+'/'+ar(b)});const blob=new Blob([bytes],{type:'application/pdf'});const fn=fname(L);
 if(share){const f=new File([blob],fn,{type:'application/pdf'});if(navigator.canShare&&navigator.canShare({files:[f]})){try{await navigator.share({files:[f],title:L.ti||'محاضرة'});return}catch(e){if(e&&e.name==='AbortError')return}}}
 const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=fn;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);tst('تم تجهيز ملف PDF');window.ZB11.lastPdf=bytes}
 catch(e){tst('تعذّر تجهيز PDF')}finally{if(btn){btn.disabled=false;btn.innerHTML=old}}}
